/**
 * Three DeepSeek AI Agents
 *
 * Agent 1 — CHAT: Client-facing assistant
 *   - Salon info, prices, booking, auth blocks, chat
 *   - Key: DEEPSEEK_API_KEY_CHAT
 *
 * Agent 2 — LANDING: Landing page + SEO generation
 *   - Newsletter landing pages, CMS blocks, SEO metadata
 *   - Key: DEEPSEEK_API_KEY_LANDING
 *
 * Agent 3 — IMAGE: Image prompt generation
 *   - Generates prompts → actual rendering via Google Gemini
 *   - Key: DEEPSEEK_API_KEY_IMAGE
 *   - NOTE: DeepSeek does not support image generation natively.
 *     Image prompts are generated by DeepSeek, then passed to Gemini Imagen.
 */

export type AgentType = "chat" | "landing" | "image";

export interface AgentConfig {
  type: AgentType;
  apiKey: string;
  model: string;
  temperature: number;
  maxTokens: number;
  rpmLimit: number;
}

export const AGENTS: Record<AgentType, AgentConfig> = {
  chat: {
    type: "chat",
    apiKey: process.env.DEEPSEEK_API_KEY_CHAT ?? "",
    model: "deepseek-chat",
    temperature: 0.5,
    maxTokens: 2000,
    rpmLimit: 10,
  },
  landing: {
    type: "landing",
    apiKey: process.env.DEEPSEEK_API_KEY_LANDING ?? "",
    model: "deepseek-chat",
    temperature: 0.3,
    maxTokens: 4000,
    rpmLimit: 5,
  },
  image: {
    type: "image",
    apiKey: process.env.DEEPSEEK_API_KEY_IMAGE ?? "",
    model: "deepseek-chat",
    temperature: 0.7,
    maxTokens: 500,
    rpmLimit: 3,
  },
};

