// ─── DeepSeek API call helper ─────────────────────────────────────────────────

export interface DeepSeekMessage {
  role: "user" | "assistant" | "system";
  content: string;
}

export interface DeepSeekOptions {
  agent: AgentType;
  messages: DeepSeekMessage[];
  stream?: boolean;
  systemPrompt?: string;
  jsonMode?: boolean;
}

export async function callDeepSeek(options: DeepSeekOptions): Promise<Response> {
  const { agent, messages, stream = false, systemPrompt, jsonMode = false } = options;
  const config = AGENTS[agent];

  if (!config.apiKey) {
    throw new Error(`DeepSeek API key not configured for agent: ${agent}`);
  }

  const allMessages: DeepSeekMessage[] = systemPrompt
    ? [{ role: "system", content: systemPrompt }, ...messages]
    : messages;

  const response = await fetch("https://api.deepseek.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${config.apiKey}`,
    },
    body: JSON.stringify({
      model: config.model,
      messages: allMessages,
      temperature: config.temperature,
      max_tokens: config.maxTokens,
      stream,
      ...(jsonMode ? { response_format: { type: "json_object" } } : {}),
    }),
  });

  return response;
}
